param([Parameter(Mandatory)][string]$Dist)
$ErrorActionPreference='Stop'
$repo=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..')); $resolved=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $Dist).Path); $temp=[IO.Path]::GetFullPath([IO.Path]::GetTempPath()); if(-not ($resolved.StartsWith($repo,[StringComparison]::OrdinalIgnoreCase) -or $resolved.StartsWith($temp,[StringComparison]::OrdinalIgnoreCase))){throw 'Installer dist escapes the repository or temp containment roots.'}; if([IO.Path]::GetFileName($resolved) -ne 'squirrel-windows'){throw 'Installer dist must be the exact squirrel-windows directory.'}; $setups=@(Get-ChildItem -LiteralPath $resolved -Filter 'Dim-Sum-Atlas-*.exe' -File); if($setups.Count -ne 1){throw "Expected exactly one Setup executable, found $($setups.Count)."}; $status=(Get-AuthenticodeSignature -LiteralPath $setups[0].FullName).Status; if($status -ne 'NotSigned'){throw "Installer signature status is $status, expected NotSigned."}; Write-Output $status
